/**
 * Interface and model declarations ("headers") as the checker sees them: from a JSON manifest (generated by
 * `describe` in a package's own environment) or from declarations written inline in a `.pbl` file.
 */
import * as ast from "../generated/ast.js";
import {
  fromAst,
  parseType,
  stableJsonText,
  surface,
  type TypeExpr,
} from "./types.js";

export interface ConfigField {
  type?: TypeExpr;
  hasDefault: boolean;
  /** the default as data, when it is a literal (for hover and docs) */
  default?: unknown;
  doc?: string;
}

export interface InterfaceDecl {
  name: string;
  kind: string;
  address?: string;
  module?: string;
  config: Record<string, ConfigField>;
  inputs?: Record<string, TypeExpr>;
  outputs?: Record<string, TypeExpr>;
  dynamicPorts: boolean;
  doc?: string;
}

export const MODEL_BLOCKS = ["compartments", "species", "parameters"] as const;
export type ModelBlock = (typeof MODEL_BLOCKS)[number];

export interface ModelDecl {
  name: string;
  source?: string;
  timeUnits?: string;
  blocks: Record<ModelBlock, Record<string, ConfigField>>;
  openBlocks: Set<string>;
  meta: Record<string, unknown>;
  notes: string[];
  doc?: string;
  isSort: boolean;
}

/** `protocol:data`; a bare name is `local:`. */
export function normalizeAddress(text: string): string {
  return text.includes(":") ? text : `local:${text}`;
}

export function shortName(address: string): string {
  const data = address.split(":", 2)[1] ?? address;
  const parts = data.replace(/^!/, "").split(".");
  return parts[parts.length - 1];
}

export function isCompositeAddress(address: string): boolean {
  return address.startsWith("local:") && shortName(address) === "Composite";
}

/**
 * The interface manifest format (`describe`, `describe_env.py`): a format shared with other tools, with types in
 * bigraph-schema's own forms. Its JSON Schema is published at `MANIFEST_SCHEMA_URL`.
 */
export const MANIFEST_VERSION = "pbg-interfaces/1";
export const MANIFEST_SCHEMA_URL =
  "https://biosimulations.github.io/process-bigraph-lang/schemas/pbg-interfaces-1.schema.json";
/** The earlier, pblang-only form (`config: {key: {type, default}}`, `doc`), still read. */
const LEGACY_MANIFEST_VERSION = "pblang-manifest/0";

export class Registry {
  readonly decls: InterfaceDecl[] = [];

  /**
   * Add a manifest's components. A component whose address is already known replaces the earlier one, so adding
   * the same manifest twice changes nothing. A manifest of another `schema_version` is rejected.
   */
  addManifest(manifest: unknown): void {
    const version = (manifest as { schema_version?: unknown })?.schema_version;
    if (
      version !== undefined &&
      version !== MANIFEST_VERSION &&
      version !== LEGACY_MANIFEST_VERSION
    )
      throw new Error(
        `unsupported manifest schema_version ${JSON.stringify(
          version,
        )}: this reader understands ${MANIFEST_VERSION}`,
      );
    const components =
      (manifest as { components?: unknown[] })?.components ?? [];
    for (const entry of components) {
      const decl = fromManifestEntry(entry as Record<string, unknown>);
      const known =
        decl.address === undefined
          ? -1
          : this.decls.findIndex((d) => d.address === decl.address);
      if (known >= 0) this.decls[known] = decl;
      else this.decls.push(decl);
    }
  }

  /** Replace every manifest-declared interface with these manifests' (an editor switching environments). */
  setManifests(manifests: unknown[]): void {
    const decls = this.decls.splice(0);
    try {
      for (const manifest of manifests) this.addManifest(manifest);
    } catch (error) {
      this.decls.splice(0, this.decls.length, ...decls);
      throw error;
    }
  }

  /** By exact address; else by unique short name (`local:Name`, or a class re-exported from another module). */
  lookup(address: string): InterfaceDecl | undefined {
    if (!address.startsWith("local:")) return undefined;
    const exact = this.decls.find((d) => d.address === address);
    if (exact) return exact;
    const name = shortName(address);
    const byName = this.decls.filter((d) => d.name === name);
    return byName.length === 1 ? byName[0] : undefined;
  }
}

function fromManifestEntry(entry: Record<string, unknown>): InterfaceDecl {
  const config: Record<string, ConfigField> = {};
  if (entry.config_schema != null && typeof entry.config_schema === "object") {
    // the shared format: the class's own config_schema; a default lives in the type (`T{v}`, `{_type, _default}`)
    for (const [key, spec] of Object.entries(
      entry.config_schema as Record<string, unknown>,
    )) {
      let type: TypeExpr | undefined;
      try {
        type = spec != null ? parseType(spec) : undefined;
      } catch {
        type = undefined;
      }
      config[key] = {
        type,
        hasDefault: type?.kind === "named" && Boolean(type.hasDefault),
      };
      if (type?.kind === "named" && type.hasDefault)
        config[key].default = type.default;
    }
  }
  for (const [key, field] of Object.entries(
    (entry.config as Record<string, Record<string, unknown>>) ?? {},
  )) {
    // pblang-manifest/0
    config[key] = {
      type: field.type != null ? parseType(field.type) : undefined,
      hasDefault: "default" in field,
    };
    if ("default" in field) config[key].default = field.default;
    if (typeof field.doc === "string") config[key].doc = field.doc;
  }
  const decl: InterfaceDecl = {
    name: String(entry.name),
    kind: String(entry.kind ?? "process"),
    address: typeof entry.address === "string" ? entry.address : undefined,
    module: typeof entry.module === "string" ? entry.module : undefined,
    config,
    inputs: portsFromManifest(entry.inputs),
    outputs: portsFromManifest(entry.outputs),
    dynamicPorts: Boolean(entry.dynamic_ports),
  };
  const description = entry.description ?? entry.doc;
  if (typeof description === "string") decl.doc = description;
  return decl;
}

function portsFromManifest(
  ports: unknown,
): Record<string, TypeExpr> | undefined {
  if (ports == null || typeof ports !== "object") return undefined;
  const out: Record<string, TypeExpr> = {};
  for (const [k, v] of Object.entries(ports as Record<string, unknown>))
    out[k] = parseType(v);
  return out;
}

// --- from the AST ---------------------------------------------------------------------------------------------

export function interfaceFromAst(
  node: ast.Interface,
  module?: string,
): InterfaceDecl {
  const decl: InterfaceDecl = {
    name: node.name,
    kind: node.kind,
    address:
      node.address !== undefined ? normalizeAddress(node.address) : undefined,
    module,
    config: fieldsOf(node.config),
    dynamicPorts: false,
  };
  const doc = docText(
    ast.isStatement(node.$container) ? node.$container.docs : [],
  );
  if (doc !== undefined) decl.doc = doc;
  if (node.inputs) {
    if (node.inputs.open) decl.dynamicPorts = true;
    else decl.inputs = portTypes(node.inputs.fields);
  }
  if (node.outputs) {
    if (node.outputs.open) decl.dynamicPorts = true;
    else decl.outputs = portTypes(node.outputs.fields);
  }
  return decl;
}

export function modelFromAst(node: ast.ModelDecl): ModelDecl {
  const decl: ModelDecl = {
    name: node.name,
    source: node.source,
    blocks: { compartments: {}, species: {}, parameters: {} },
    openBlocks: new Set(),
    meta: {},
    notes: [],
    isSort: node.source === undefined,
  };
  const doc = docText(
    ast.isStatement(node.$container) ? node.$container.docs : [],
  );
  if (doc !== undefined) decl.doc = doc;
  for (const item of node.items) {
    if (ast.isModelTime(item)) decl.timeUnits = item.units;
    else if (ast.isModelMeta(item)) decl.meta = dictValue(item.block);
    else if (ast.isModelBlock(item)) {
      Object.assign(
        decl.blocks[item.kind as ModelBlock],
        fieldsOf(item.fields),
      );
      if (item.open) decl.openBlocks.add(item.kind);
    }
  }
  return decl;
}

export function fieldsOf(fields: ast.Field[]): Record<string, ConfigField> {
  const out: Record<string, ConfigField> = {};
  for (const field of fields) {
    const entry: ConfigField = {
      type: fromAst(field.type),
      hasDefault: field.default !== undefined,
    };
    if (field.default !== undefined) {
      const value = literalValue(field.default);
      if (value !== undefined) entry.default = value;
    }
    const doc = docText(field.docs);
    if (doc !== undefined) entry.doc = doc;
    out[field.name] = entry;
  }
  return out;
}

/** The text of `///` doc comments, without the markers. */
export function docText(docs: string[]): string | undefined {
  if (docs.length === 0) return undefined;
  return docs.map((d) => d.replace(/^\/\/\/ ?/, "").trim()).join(" ");
}

function portTypes(fields: ast.Field[]): Record<string, TypeExpr> {
  const out: Record<string, TypeExpr> = {};
  for (const field of fields) out[field.name] = fromAst(field.type);
  return out;
}

/** A literal value from the AST (dict/list/tuple/scalars); non-literal values come back as `undefined`. */
export function literalValue(value: ast.Value): unknown {
  if (ast.isIntLiteral(value))
    return BigInt(value.$cstNode?.text.trim() ?? String(value.value));
  if (ast.isFloatLiteral(value) || ast.isStringLiteral(value))
    return value.value;
  if (ast.isBoolLiteral(value)) return value.value === "true";
  if (ast.isNullLiteral(value)) return null;
  if (ast.isListLiteral(value) || ast.isTupleLiteral(value))
    return value.items.map(literalValue);
  if (ast.isDictLiteral(value)) return dictValue(value);
  return undefined;
}

export function dictValue(dict: {
  entries: { key: string; value: ast.Value }[];
}): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const entry of dict.entries) out[entry.key] = literalValue(entry.value);
  return out;
}

// --- rendering ------------------------------------------------------------------------------------------------

/** The declaration in DSL spelling, as a header file prints it (for hover). */
export function renderInterface(decl: InterfaceDecl): string {
  const lines: string[] = [];
  const at =
    decl.address !== undefined ? ` at ${JSON.stringify(decl.address)}` : "";
  lines.push(`${decl.kind} ${decl.name}${at} {`);
  const config = Object.entries(decl.config);
  if (config.length > 0)
    lines.push(
      `  config { ${config.map(([k, f]) => renderField(k, f)).join(" ")} }`,
    );
  for (const [label, ports] of [
    ["inputs", decl.inputs],
    ["outputs", decl.outputs],
  ] as const) {
    if (ports === undefined) {
      if (decl.dynamicPorts) lines.push(`  ${label} { ... }`);
      continue;
    }
    const fields = Object.entries(ports).map(
      ([k, t]) => `${k}: ${surface(t)};`,
    );
    lines.push(`  ${label} { ${fields.join(" ")} }`);
  }
  lines.push("}");
  return lines.join("\n");
}

export function renderField(name: string, field: ConfigField): string {
  let text = `${name}: ${field.type ? surface(field.type) : "any"}`;
  if (field.default !== undefined)
    text += ` = ${stableJsonText(field.default)}`;
  else if (field.hasDefault) text += " = ...";
  return `${text};`;
}
